  /**
   * @method
   * @name paradex#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see https://docs.paradex.trade/api/prod/orders/get-orders
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.side] 'buy' or 'sell'
   * @param {boolean} [params.paginate] set to true if you want to fetch orders
   * with pagination
   * @param {int} params.until timestamp in ms of the latest order to fetch
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->authenticateRest());
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOrders"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallCursor(
                       std::string("fetchOrders"), symbol, since, limit, params,
                       std::string("next"), std::string("cursor"), ccxt::any{},
                       50));
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("market"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start_at"), since);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("page_size"), limit);
                 }
                 ccxt::any requestparamsVariable = this->handleUntilOption(
                     std::string("end_at"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 ccxt::any response = awaitValue(this->privateGetOrdersHistory(
                     this->extend(request, params)));
                 //
                 // {
                 //     "next":
                 //     "eyJmaWx0ZXIiMsIm1hcmtlciI6eyJtYXJrZXIiOiIxNjc1NjUwMDE3NDMxMTAxNjk5N=",
                 //     "prev":
                 //     "eyJmaWx0ZXIiOnsiTGltaXQiOjkwfSwidGltZSI6MTY4MTY3OTgzNzk3MTMwOTk1MywibWFya2VyIjp7Im1zMjExMD==",
                 //     "results": [
                 //       {
                 //         "account":
                 //         "0x4638e3041366aa71720be63e32e53e1223316c7f0d56f7aa617542ed1e7512x",
                 //         "avg_fill_price": "26000",
                 //         "cancel_reason": "NOT_ENOUGH_MARGIN",
                 //         "client_id": "x1234",
                 //         "created_at": 1681493746016,
                 //         "flags": [
                 //           "REDUCE_ONLY"
                 //         ],
                 //         "id": "123456",
                 //         "instruction": "GTC",
                 //         "last_updated_at": 1681493746016,
                 //         "market": "BTC-USD-PERP",
                 //         "price": "26000",
                 //         "published_at": 1681493746016,
                 //         "received_at": 1681493746016,
                 //         "remaining_size": "0",
                 //         "seq_no": 1681471234972000000,
                 //         "side": "BUY",
                 //         "size": "0.05",
                 //         "status": "NEW",
                 //         "stp": "EXPIRE_MAKER",
                 //         "timestamp": 1681493746016,
                 //         "trigger_price": "26000",
                 //         "type": "MARKET"
                 //       }
                 //     ]
                 //   }
                 //
                 ccxt::any orders = this->safeList(
                     response, std::string("results"), ccxt::list{});
                 ccxt::any paginationCursor =
                     this->safeString(response, std::string("next"));
                 ccxt::any ordersLength = getArrayLength(orders);
                 if (isTrue(isTrue((!isEqual(paginationCursor, ccxt::any{}))) &&
                            isTrue((isGreaterThan(ordersLength, 0))))) {
                   ccxt::any first = ::getValue(orders, 0);
                   ::setValue(first, std::string("next"), paginationCursor);
                   ::setValue(orders, 0, first);
                 }
                 return this->parseOrders(orders, market, since, limit);
               })
        .share();
  }

