  /**
   * @method
   * @name paradex#fetchBalance
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @see https://docs.paradex.trade/api/prod/account/get-balance
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<ccxt::any>
  fetchBalance(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        awaitValue(this->authenticateRest());
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any response =
                            awaitValue(this->privateGetBalance());
                        //
                        //     {
                        //         "results": [
                        //             {
                        //                 "token": "USDC",
                        //                 "size": "99980.2382266290601",
                        //                 "last_updated_at": 1718529757240
                        //             }
                        //         ]
                        //     }
                        //
                        ccxt::any data = this->safeList(
                            response, std::string("results"), ccxt::list{});
                        return this->parseBalance(data);
                      })
        .share();
  }

  ccxt::any parseBalance(ccxt::any response) override {
    ccxt::any result = ccxt::dict{
        {std::string("info"), response},
    };
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(response));
         postFixIncrement(i)) {
      ccxt::any balance = this->safeDict(response, i, ccxt::dict{});
      ccxt::any currencyId = this->safeString(balance, std::string("token"));
      ccxt::any code = this->safeCurrencyCode(currencyId);
      ccxt::any account = this->account();
      ::setValue(account, std::string("total"),
                 this->safeString(balance, std::string("size")));
      if (isTrue(!isEqual(code, ccxt::any{}))) {
        ::setValue(result, code, account);
      }
    }
    return this->safeBalance(result);
  }

  /**
   * @method
   * @name paradex#fetchMyTrades
   * @description fetch all trades made by the user
   * @see https://docs.paradex.trade/api/prod/account/list-fills
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [available
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @param {int} [params.until] the latest time in ms to fetch entries for
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<ccxt::any>
  fetchMyTrades(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->authenticateRest());
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchMyTrades"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallCursor(
                       std::string("fetchMyTrades"), symbol, since, limit,
                       params, std::string("next"), std::string("cursor"),
                       ccxt::any{}, 100));
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("market"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("page_size"), limit);
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start_at"), since);
                 }
                 ccxt::any requestparamsVariable = this->handleUntilOption(
                     std::string("end_at"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 ccxt::any response = awaitValue(
                     this->privateGetFills(this->extend(request, params)));
                 //
                 //     {
                 //         "next": null,
                 //         "prev": null,
                 //         "results": [
                 //             {
                 //                 "id": "1718947571560201703986670002",
                 //                 "side": "BUY",
                 //                 "liquidity": "TAKER",
                 //                 "market": "BTC-USD-PERP",
                 //                 "order_id": "1718947571540201703992340000",
                 //                 "price": "64852.9",
                 //                 "size": "0.01",
                 //                 "fee": "0.1945587",
                 //                 "fee_currency": "USDC",
                 //                 "created_at": 1718947571569,
                 //                 "remaining_size": "0",
                 //                 "client_id": "",
                 //                 "fill_type": "FILL"
                 //             }
                 //         ]
                 //     }
                 //
                 ccxt::any trades = this->safeList(
                     response, std::string("results"), ccxt::list{});
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(trades));
                      postFixIncrement(i)) {
                   ::setValue(::getValue(trades, i), std::string("next"),
                              this->safeString(response, std::string("next")));
                 }
                 return this->parseTrades(trades, market, since, limit);
               })
        .share();
  }

