                 //
                 // {
                 //     "account":
                 //     "0x6343248026a845b39a8a73fbe9c7ef0a841db31ed5c61ec1446aa9d25e54dbc",
                 //     "configs": [
                 //         {
                 //             "market": "SOL-USD-PERP",
