  ccxt::any parseLeverage(ccxt::any leverage,
                          ccxt::any market = ccxt::any{}) override {
    ccxt::any marketId = this->safeString(leverage, std::string("market"));
    market = this->safeMarket(marketId, market);
    ccxt::any marginMode =
        this->safeStringLower(leverage, std::string("margin_type"));
    return ccxt::dict{
        {std::string("info"), leverage},
        {std::string("symbol"), this->safeSymbol(marketId, market)},
        {std::string("marginMode"), marginMode},
        {std::string("longLeverage"),
         this->safeInteger(leverage, std::string("leverage"))},
        {std::string("shortLeverage"),
         this->safeInteger(leverage, std::string("leverage"))},
    };
  }

  virtual ccxt::any encodeMarginMode(ccxt::any mode) {
    ccxt::any modes = ccxt::dict{
        {std::string("cross"), std::string("CROSS")},
        {std::string("isolated"), std::string("ISOLATED")},
    };
    return this->safeString(modes, mode, mode);
  }

  /**
   * @method
   * @name paradex#setLeverage
   * @description set the level of leverage for a market
   * @see https://docs.paradex.trade/api/prod/account/upsert-account-margin
   * @param {float} leverage the rate of leverage
   * @param {string} [symbol] unified market symbol (is mandatory for swap
   * markets)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.marginMode] 'cross' or 'isolated'
   * @returns {object} response from the exchange
   */
  std::shared_future<ccxt::any>
  setLeverage(ccxt::any leverage, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        this->checkRequiredArgument(std::string("setLeverage"),
                                                    symbol,
                                                    std::string("symbol"));
                        awaitValue(this->authenticateRest());
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any marginMode = ccxt::any{};
                        ccxt::any marginModeparamsVariable =
                            this->handleMarginModeAndParams(
                                std::string("setLeverage"), params,
                                std::string("cross"));
                        marginMode = ::getValue(marginModeparamsVariable, 0);
                        params = ::getValue(marginModeparamsVariable, 1);
                        ccxt::any request = ccxt::dict{
                            {std::string("market"),
                             ::getValue(market, std::string("id"))},
                            {std::string("leverage"), leverage},
                            {std::string("margin_type"),
                             this->encodeMarginMode(marginMode)},
                        };
                        return awaitValue(this->privatePostAccountMarginMarket(
                            this->extend(request, params)));
                      })
        .share();
  }

