  ccxt::any parseGreeks(ccxt::any greeks,
                        ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "symbol": "BTC-USD-114000-P",
    //         "mark_price": "10835.66892602",
    //         "mark_iv": "0.71781855",
    //         "delta": "-0.98726024",
    //         "greeks": {
    //             "delta": "-0.9872602390817709",
    //             "gamma": "0.000004560958862297231",
    //             "vega": "227.11344863639806",
    //             "rho": "-302.0617972461581",
    //             "vanna": "0.06609830491614832",
    //             "volga": "925.9501532805552"
    //         },
    //         "last_traded_price": "10551.5",
    //         "bid": "10794.9",
    //         "bid_iv": "0.05",
    //         "ask": "10887.3",
    //         "ask_iv": "0.8783283",
    //         "last_iv": "0.05",
    //         "volume_24h": "0",
    //         "total_volume": "195240.72672261014",
    //         "created_at": 1747644009995,
    //         "underlying_price": "103164.79162649",
    //         "open_interest": "0",
    //         "funding_rate": "0.000004464241170536191",
    //         "price_change_rate_24h": "0.074915",
    //         "future_funding_rate": "0.0001"
    //     }
    //
    ccxt::any marketId = this->safeString(greeks, std::string("symbol"));
    market =
        this->safeMarket(marketId, market, ccxt::any{}, std::string("option"));
    ccxt::any symbol = ::getValue(market, std::string("symbol"));
    ccxt::any timestamp = this->safeInteger(greeks, std::string("created_at"));
    ccxt::any greeksData =
        this->safeDict(greeks, std::string("greeks"), ccxt::dict{});
    return ccxt::dict{
        {std::string("symbol"), symbol},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("delta"),
         this->safeNumber(greeksData, std::string("delta"))},
        {std::string("gamma"),
         this->safeNumber(greeksData, std::string("gamma"))},
        {std::string("theta"), ccxt::any{}},
        {std::string("vega"),
         this->safeNumber(greeksData, std::string("vega"))},
        {std::string("rho"), this->safeNumber(greeksData, std::string("rho"))},
        {std::string("vanna"),
         this->safeNumber(greeksData, std::string("vanna"))},
        {std::string("volga"),
         this->safeNumber(greeksData, std::string("volga"))},
        {std::string("bidSize"), ccxt::any{}},
        {std::string("askSize"), ccxt::any{}},
        {std::string("bidImpliedVolatility"),
         this->safeNumber(greeks, std::string("bid_iv"))},
        {std::string("askImpliedVolatility"),
         this->safeNumber(greeks, std::string("ask_iv"))},
        {std::string("markImpliedVolatility"),
         this->safeNumber(greeks, std::string("mark_iv"))},
        {std::string("bidPrice"), this->safeNumber(greeks, std::string("bid"))},
        {std::string("askPrice"), this->safeNumber(greeks, std::string("ask"))},
        {std::string("markPrice"),
         this->safeNumber(greeks, std::string("mark_price"))},
        {std::string("lastPrice"),
         this->safeNumber(greeks, std::string("last_traded_price"))},
        {std::string("underlyingPrice"),
         this->safeNumber(greeks, std::string("underlying_price"))},
        {std::string("info"), greeks},
    };
  }

  /**
   * @method
   * @name paradex#fetchFundingHistory
   * @description fetch the history of funding payments paid and received on
   * this account
   * @see https://docs.paradex.trade/api/prod/account/get-funding
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch funding history for
   * @param {int} [limit] the maximum number of funding history structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.cursor] returns the next paginated page
   * @param {int} [params.until] the latest time in ms to fetch entries for
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [available
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {object[]} a list of [funding history structures]{@link
   * https://docs.ccxt.com/?id=funding-history-structure}
   */
  std::shared_future<ccxt::any> fetchFundingHistory(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchFundingHistory() requires "
                                             "a symbol argument"))));
                 }
                 awaitValue(this->authenticateRest());
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchFundingHistory"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallCursor(
                       std::string("fetchFundingHistory"), symbol, since, limit,
                       params, std::string("next"), std::string("cursor"),
                       ccxt::any{}, 100));
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("page_size"),
                              mathMin(limit, 5000));
                 } else {
                   ::setValue(request, std::string("page_size"), 100);
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start_at"), since);
                 }
                 ccxt::any requestparamsVariable = this->handleUntilOption(
                     std::string("end_at"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 ccxt::any response =
                     awaitValue(this->privateGetFundingPayments(
                         this->extend(request, params)));
                 //
                 // {
                 //     "next":
                 //     "eyJmaWx0ZXIiMsIm1hcmtlciI6eyJtYXJrZXIiOiIxNjc1NjUwMDE3NDMxMTAxNjk5N=",
                 //     "prev":
                 //     "eyJmaWx0ZXIiOnsiTGltaXQiOjkwfSwidGltZSI6MTY4MTY3OTgzNzk3MTMwOTk1MywibWFya2VyIjp7Im1zMjExMD==",
                 //     "results": [
                 //         {
                 //             "account": "string",
                 //             "created_at": 1681375481000,
                 //             "fill_id": "8615262148007718462",
                 //             "id": "1681375578221101699352320000",
                 //             "index": "-2819.53434361",
                 //             "market": "BTC-USD-PERP",
                 //             "payment": "34.4490622"
                 //         }
                 //     ]
                 // }
                 //
                 ccxt::any results = this->safeList(
                     response, std::string("results"), ccxt::list{});
                 return this->parseIncomes(results, market, since, limit);
               })
        .share();
  }

  ccxt::any parseIncome(ccxt::any income,
                        ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "account": "string",
    //         "created_at": 1681375481000,
    //         "fill_id": "8615262148007718462",
    //         "id": "1681375578221101699352320000",
    //         "index": "-2819.53434361",
    //         "market": "BTC-USD-PERP",
    //         "payment": "34.4490622"
    //     }
    //
    ccxt::any marketId = this->safeString(income, std::string("market"));
    market = this->safeMarket(marketId, market);
    ccxt::any timestamp = this->safeInteger(income, std::string("created_at"));
    return ccxt::dict{
        {std::string("info"), income},
        {std::string("symbol"), ::getValue(market, std::string("symbol"))},
        {std::string("code"), ::getValue(market, std::string("settle"))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("id"), this->safeString(income, std::string("id"))},
        {std::string("amount"),
         this->safeNumber(income, std::string("payment"))},
    };
  }

  /**
   * @method
   * @name paradex#fetchFundingRateHistory
   * @description fetches historical funding rate prices
   * @see https://docs.paradex.trade/api/prod/markets/get-funding-data
   * @param {string} symbol unified symbol of the market to fetch the funding
   * rate history for
   * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
   * @param {int} [limit] the maximum amount of funding rate structures
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest funding rate to
   * fetch
   * @returns {object[]} a list of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure}
   */
  std::shared_future<ccxt::any> fetchFundingRateHistory(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchFundingRateHistory() "
                                             "requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("page_size"),
                              mathMin(limit, 5000)); // api maximum 5000
                 } else {
                   ::setValue(request, std::string("page_size"),
                              1000); // max is 5000
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start_at"), since);
                 }
                 ccxt::any until =
                     this->safeInteger(params, std::string("until"));
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   params = this->omit(params, std::string("until"));
                   ::setValue(request, std::string("end_at"), until);
                 }
                 ccxt::any response = awaitValue(
                     this->publicGetFundingData(this->extend(request, params)));
                 //
                 // {
                 //     "next":
                 //     "eyJmaWx0ZXIiMsIm1hcmtlciI6eyJtYXJrZXIiOiIxNjc1NjUwMDE3NDMxMTAxNjk5N=",
                 //     "prev":
                 //     "eyJmaWx0ZXIiOnsiTGltaXQiOjkwfSwidGltZSI6MTY4MTY3OTgzNzk3MTMwOTk1MywibWFya2VyIjp7Im1zMjExMD==",
                 //     "results": [
                 //          {
                 //              "market":"BTC-USD-PERP",
                 //              "funding_index":"20511.93608234044552",
                 //              "funding_premium":"-6.04646651485986656",
                 //              "funding_rate":"-0.00006992598926",
                 //              "funding_rate_8h":"",
                 //              "funding_period_hours":0,
                 //              "created_at":1764160327843
                 //          }
                 //     ]
                 // }
                 //
                 ccxt::any results = this->safeList(
                     response, std::string("results"), ccxt::list{});
                 ccxt::any rates = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(results));
                      postFixIncrement(i)) {
                   ccxt::any rate = ::getValue(results, i);
                   ccxt::any timestamp =
                       this->safeInteger(rate, std::string("created_at"));
                   ccxt::any datetime = this->iso8601(timestamp);
                   arrayPush(rates,
                             ccxt::dict{
                                 {std::string("info"), rate},
                                 {std::string("symbol"),
                                  ::getValue(market, std::string("symbol"))},
                                 {std::string("fundingRate"),
                                  this->safeNumber(
                                      rate, std::string("funding_rate"))},
                                 {std::string("timestamp"), timestamp},
                                 {std::string("datetime"), datetime},
                             });
                 }
                 ccxt::any sorted =
                     this->sortBy(rates, std::string("timestamp"));
                 return this->filterBySymbolSinceLimit(
                     sorted, ::getValue(market, std::string("symbol")), since,
                     limit);
               })
        .share();
  }

  ccxt::any sign(ccxt::any path, ccxt::any api = std::string("public"),
                 ccxt::any method = std::string("GET"),
                 ccxt::any params = ccxt::dict{},
                 ccxt::any headers = ccxt::any{},
                 ccxt::any body = ccxt::any{}) override {
    ccxt::any version = this->version;
    if (isTrue(isEqual(getIndexOf(path, std::string("v2/")), 0))) {
      version = std::string("v2");
      path = replace(path, std::string("v2/"), std::string(""));
    }
    ccxt::any url =
        add(add(this->implodeHostname(::getValue(
                    ::getValue(this->urls, std::string("api")), version)),
                std::string("/")),
            this->implodeParams(path, params));
    ccxt::any query = this->omit(params, this->extractParams(path));
    if (isTrue(isEqual(api, std::string("public")))) {
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
        url = add(url, add(std::string("?"), this->urlencode(query)));
      }
    } else if (isTrue(isEqual(api, std::string("private")))) {
      headers = ccxt::dict{
          {std::string("Accept"), std::string("application/json")},
          {std::string("PARADEX-PARTNER"),
           this->safeString(this->options, std::string("broker"),
                            std::string("CCXT"))},
      };
      // TODO: optimize
      if (isTrue(isEqual(path, std::string("auth")))) {
        ::setValue(headers, std::string("PARADEX-STARKNET-ACCOUNT"),
                   ::getValue(query, std::string("account")));
        ::setValue(headers, std::string("PARADEX-STARKNET-SIGNATURE"),
                   ::getValue(query, std::string("signature")));
        ::setValue(headers, std::string("PARADEX-TIMESTAMP"),
                   toString(::getValue(query, std::string("timestamp"))));
        ::setValue(headers, std::string("PARADEX-SIGNATURE-EXPIRATION"),
                   toString(::getValue(query, std::string("expiration"))));
      } else if (isTrue(isEqual(path, std::string("onboarding")))) {
        ::setValue(headers, std::string("PARADEX-ETHEREUM-ACCOUNT"),
                   this->walletAddress);
        ::setValue(headers, std::string("PARADEX-STARKNET-ACCOUNT"),
                   ::getValue(query, std::string("account")));
        ::setValue(headers, std::string("PARADEX-STARKNET-SIGNATURE"),
                   ::getValue(query, std::string("signature")));
        ::setValue(headers, std::string("PARADEX-TIMESTAMP"),
                   toString(this->nonce()));
        ::setValue(headers, std::string("Content-Type"),
                   std::string("application/json"));
        body = this->json(ccxt::dict{
            {std::string("public_key"),
             ::getValue(query, std::string("public_key"))},
        });
      } else {
        ccxt::any token = ::getValue(this->options, std::string("authToken"));
        ::setValue(headers, std::string("Authorization"),
                   add(std::string("Bearer "), token));
        if (isTrue(isTrue(isTrue((isEqual(method, std::string("POST")))) ||
                          isTrue((isEqual(method, std::string("PUT"))))) ||
                   isTrue((isTrue((isEqual(method, std::string("DELETE")))) &&
                           isTrue((isEqual(path,
                                           std::string("orders/batch")))))))) {
          ::setValue(headers, std::string("Content-Type"),
                     std::string("application/json"));
          body = this->json(query);
        } else {
          url = add(add(url, std::string("?")), this->urlencode(query));
        }
      }
    }
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }

  ccxt::any handleErrors(ccxt::any httpCode, ccxt::any reason, ccxt::any url,
                         ccxt::any method, ccxt::any headers, ccxt::any body,
                         ccxt::any response, ccxt::any requestHeaders,
                         ccxt::any requestBody) override {
    if (isTrue(isEqual(response, ccxt::any{}))) {
      return ccxt::any{}; // fallback to default error handler
    }
    //
    //     {
    //         "data": null,
    //         "error": "NOT_ONBOARDED",
    //         "message": "User has never called /onboarding endpoint"
    //     }
    //
    ccxt::any errorCode = this->safeString(response, std::string("error"));
    if (isTrue(!isEqual(errorCode, ccxt::any{}))) {
      ccxt::any feedback = add(add(this->id, std::string(" ")), body);
      this->throwBroadlyMatchedException(
          ::getValue(this->exceptions, std::string("broad")), body, feedback);
      this->throwExactlyMatchedException(
          ::getValue(this->exceptions, std::string("exact")), errorCode,
          feedback);
      throw ExchangeError(toString(feedback));
    }
    return ccxt::any{};
  }
